matched_invariants.solidity:
require(target != address(this));
uint256 balance_sender = balanceOf(address(this));
uint256 balance_receiver = balanceOf(target);
require(balance_sender > 2);
uint256 transfer_value = (amount % balance_sender) + 1;
bool r = this.transfer(target, transfer_value);
assertWithMsg(r == true, "transfer failed");
assertEq(balanceOf(address(this)), balance_sender - transfer_value, "Wrong source balance after transfer");
assertEq(balanceOf(target), balance_receiver + transfer_value, "Wrong target balance after transfer");

require(target != address(this));
require(target != msg.sender);
uint256 balance_sender = balanceOf(msg.sender);
uint256 balance_receiver = balanceOf(target);
uint256 current_allowance = allowance(msg.sender, address(this));
require(balance_sender > 2 && current_allowance > balance_sender);
uint256 transfer_value = (amount % balance_sender) + 1;
bool r = transferFrom(msg.sender, target, transfer_value);
assertWithMsg(r == true, "transferFrom failed");
assertEq(balanceOf(msg.sender), balance_sender - transfer_value, "Wrong source balance after transferFrom");
assertEq(balanceOf(target), balance_receiver + transfer_value, "Wrong target balance after transferFrom");

require(target != address(this) && target != address(0));
require(target != msg.sender);
uint256 balance_sender = balanceOf(msg.sender);
uint256 current_allowance = allowance(msg.sender, address(this));
require(balance_sender > 0 && current_allowance > balance_sender);
uint256 transfer_value = (amount % balance_sender) + 1;
bool r = this.transferFrom(msg.sender, target, transfer_value);
assertWithMsg(r == true, "transferFrom failed");
if (current_allowance != type(uint256).max) {
    assertEq(allowance(msg.sender, address(this)), current_allowance - transfer_value, "Allowance not updated correctly");
}

uint256 balance_sender = balanceOf(address(this));
uint256 balance_receiver = balanceOf(target);
require(balance_sender > 0);
bool r = this.transfer(target, balance_sender + 1);
assertWithMsg(r == false, "Successful transfer for more than account balance");
assertEq(balanceOf(address(this)), balance_sender, "Transfer for more than balance modified source balance");
assertEq(balanceOf(target), balance_receiver, "Transfer for more than balance modified target balance");

uint256 balance_sender = balanceOf(msg.sender);
uint256 balance_receiver = balanceOf(target);
uint256 current_allowance = allowance(msg.sender, address(this));
require(balance_sender > 0 && current_allowance > balance_sender);
bool r = transferFrom(msg.sender, target, balance_sender + 1);
assertWithMsg(r == false, "Successful transferFrom for more than account balance");
assertEq(balanceOf(msg.sender), balance_sender, "TransferFrom for more than balance modified source balance");
assertEq(balanceOf(target), balance_receiver, "TransferFrom for more than balance modified target balance");

uint256 balance_receiver = balanceOf(target);
uint256 supply = totalSupply();
this.mint(target, amount);
assertEq(balanceOf(target), balance_receiver + amount, "Mint failed to update target balance");
assertEq(totalSupply(), supply + amount, "Mint failed to update total supply");

uint256 balance_sender = balanceOf(address(this));
require(balance_sender > 0);
bool r = this.transfer(address(this), value % (balance_sender + 1));
assertWithMsg(r == true, "Failed self transfer");
assertEq(balance_sender, balanceOf(address(this)), "Self transfer breaks accounting");

uint256 balance_sender = balanceOf(msg.sender);
uint256 current_allowance = allowance(msg.sender, address(this));
require(balance_sender > 0 && current_allowance > 0);
uint256 maxValue = balance_sender >= current_allowance ? current_allowance : balance_sender;
bool r = transferFrom(msg.sender, msg.sender, value % (maxValue + 1));
assertWithMsg(r == true, "Failed self transferFrom");
assertEq(balance_sender, balanceOf(msg.sender), "Self transferFrom breaks accounting");

uint256 balance_sender = balanceOf(address(this));
uint256 supply = totalSupply();
require(balance_sender > 0);
uint256 burn_amount = amount % (balance_sender + 1);
this.burn(burn_amount);
assertEq(balanceOf(address(this)), balance_sender - burn_amount, "Source balance incorrect after burn");
assertEq(totalSupply(), supply - burn_amount, "Total supply incorrect after burn");

